TIPOS = [
    ("refugio", "Refugio o alojamiento", "bueno", "casa"),
    ("acopio", "Centro de acopio", "ayuda", "manos"),
    ("entrega", "Entrega de ayuda", "bueno", "corazon"),
    ("transporte", "Transporte solidario", "bueno", "corazon"),
    ("servicio", "Servicio para familias afectadas", "bueno", "corazon"),
    ("pedido_ayuda", "Pedido de ayuda", "ayuda", "manos"),
]


def crear_tipos(apps, schema_editor):
    TipoRiesgo = apps.get_model("reportes", "TipoRiesgo")
    for orden, (codigo, nombre, clase, icono) in enumerate(TIPOS, start=60):
        if TipoRiesgo.objects.filter(codigo=codigo).exists() or TipoRiesgo.objects.filter(nombre__iexact=nombre).exists():
            continue
        TipoRiesgo.objects.create(codigo=codigo, nombre=nombre, clase=clase, icono=icono, plazo_horas=72, orden=orden, activo=False)


